'use client';

import { RoomMember } from "@/types/room-member";
import { Room } from "@/types/room";
import { Icons } from "@/components/icons";

import { Message } from "@/types/message";
import { StorageService } from "@/services/storage.service";

interface RoomDetailsProps {
    room: Room | null;
    members: RoomMember[];
    messages?: Message[]; // Optional now, but passed from parent
    currentUserId: string | null;
    onCloseRoom?: () => void;
}

export default function RoomDetails({ room, members, messages = [], currentUserId, onCloseRoom }: RoomDetailsProps) {
    if (!room) return null;

    const isCreator = room.creator.$id === currentUserId;
    const mediaMessages = messages.filter(m => (m.type === 'IMAGE' || m.type === 'FILE') && m.file_id);

    return (
        <aside className="w-80 bg-surface-base dark:bg-surface-darkElevated border-l border-border-default dark:border-border-darkDefault p-6 overflow-y-auto hidden md:block">
            {/* Header */}
            <div className="flex justify-between items-center mb-6">
                <h3 className="font-semibold text-text-primary dark:text-text-darkPrimary">Room Details</h3>
                <button className="text-text-muted hover:text-text-primary dark:text-text-darkMuted dark:hover:text-text-darkPrimary transition"><Icons.Close className="w-5 h-5" /></button>
            </div>

            {/* Creator or Actions */}
            <section className="mb-8">
                <p className="text-xs text-text-secondary dark:text-text-darkSecondary mb-2 font-medium">ACTIONS</p>
                {isCreator ? (
                    <button
                        onClick={onCloseRoom}
                        disabled={room.status === 'CLOSED'}
                        className={`w-full border py-3 rounded-xl transition flex items-center justify-center gap-2 ${room.status === 'CLOSED' ? 'border-border-default dark:border-border-darkDefault text-text-muted dark:text-text-darkMuted cursor-not-allowed' : 'border-status-danger/30 text-status-danger dark:text-status-dangerDark hover:bg-status-danger/10'}`}
                    >
                        {room.status === 'CLOSED' ? 'Room Closed' : <><Icons.Lock className="w-4 h-4" /> Close Room</>}
                    </button>
                ) : (
                    <button className="w-full border border-border-default dark:border-border-darkDefault text-text-secondary dark:text-text-darkSecondary py-3 rounded-xl hover:bg-surface-subtle dark:hover:bg-surface-darkSubtle transition">
                        Exit Room
                    </button>
                )}
            </section>

            {/* Members */}
            <section className="mb-8">
                <p className="text-xs text-text-secondary dark:text-text-darkSecondary mb-4 font-medium">MEMBERS ({members.length})</p>
                {members.map(member => (
                    <Member
                        key={member.$id}
                        name={member.user.$id === currentUserId ? "You" : `User ${member.user.username.substring(0, 5)}`}
                        online={member.isActive}
                    />
                ))}
            </section>

            {/* Media */}
            <section>
                <div className="flex justify-between mb-3">
                    <p className="text-xs text-text-secondary dark:text-text-darkSecondary font-medium">SHARED MEDIA</p>
                    <span className="text-xs text-brand-primary dark:text-brand-primaryDark cursor-pointer hover:underline">View All</span>
                </div>

                {mediaMessages.length === 0 ? (
                    <div className="h-28 rounded-xl bg-surface-subtle dark:bg-surface-darkSubtle flex items-center justify-center text-xs text-text-muted dark:text-text-darkMuted border border-border-default dark:border-border-darkDefault border-dashed">
                        No Media
                    </div>
                ) : (
                    <div className="grid grid-cols-2 gap-3">
                        {mediaMessages.slice(0, 6).map(msg => (
                            <a
                                key={msg.$id}
                                href={msg.file_id ? StorageService.getFileView(msg.file_id).toString() : '#'}
                                target="_blank"
                                rel="noreferrer"
                                className="block aspect-square rounded-xl overflow-hidden bg-surface-subtle dark:bg-surface-darkSubtle border border-border-default dark:border-border-darkDefault hover:opacity-90 transition relative group"
                            >
                                {msg.type === 'IMAGE' && msg.file_id ? (
                                    // eslint-disable-next-line @next/next/no-img-element
                                    <img
                                        src={StorageService.getFilePreview(msg.file_id, 150, 150).toString()}
                                        alt={msg.file_name}
                                        className="w-full h-full object-cover"
                                    />
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center p-2 text-center">
                                        <Icons.Paperclip className="w-6 h-6 text-brand-primary dark:text-brand-primaryDark mb-1" />
                                        <span className="text-[10px] text-text-secondary dark:text-text-darkSecondary truncate w-full">{msg.file_name}</span>
                                    </div>
                                )}
                            </a>
                        ))}
                    </div>
                )}
            </section>
        </aside>
    );
}

function Member({ name, online }: { name: string; online?: boolean }) {
    return (
        <div className="flex items-center gap-3 mb-3">
            <div className="w-9 h-9 rounded-full bg-brand-muted dark:bg-brand-mutedDark flex items-center justify-center text-xs text-brand-primary dark:text-brand-primaryDark font-bold">
                {name.charAt(0)}
            </div>
            <div>
                <p className="text-sm font-medium text-text-primary dark:text-text-darkPrimary">{name}</p>
                <p className={`text-xs ${online ? "text-status-success dark:text-status-successDark" : "text-text-muted dark:text-text-darkMuted"}`}>
                    {online ? "active" : "inactive"}
                </p>
            </div>
        </div>
    );
}


