import { useEffect, useCallback } from 'react';
import { Message, MessagePayload } from '@/types/message';
import { client, DB_ID, COLLECTIONS } from '@/lib/appwrite';
import { useSession } from './useSession';
import { useAppSelector, useAppDispatch } from '@/store/hooks';
import {
    fetchMessages,
    sendMessage as sendMessageAction,
    receivedMessage,
    clearMessages
} from '@/store/slices/messageSlice';

export function useMessages(roomId: string) {
    const { isAuthenticated, session, user } = useSession();

    const dispatch = useAppDispatch();
    const { messages, loading, error } = useAppSelector((state) => state.messages);

    const refresh = useCallback(() => {
        if (roomId) {
            dispatch(fetchMessages(roomId));
        } else {
            dispatch(clearMessages());
        }
    }, [dispatch, roomId]);

    useEffect(() => {
        refresh();

        const unsubscribe = client.subscribe(
            `databases.${DB_ID}.collections.${COLLECTIONS.MESSAGES}.documents`,
            (response) => {
                const payload = response.payload as Message;
                if (payload.room !== roomId) return;

                if (response.events.includes('databases.*.collections.*.documents.*.create')) {
                    // Check if message already exists (optimistic update or duplicates)
                    // The reducer logic: receivedMessage just pushes.
                    // Ideally we should check if ID exists in selector, but for now we just dispatch.
                    // The slice should arguably handle deduplication, but let's assume valid stream.
                    // To be safe, we can check here? accessing state outside component is hard.
                    // Let's just dispatch.
                    dispatch(receivedMessage(payload));
                }
            }
        );

        return () => {
            unsubscribe();
        };
    }, [dispatch, refresh, roomId]);

    const sendMessage = async (payload: MessagePayload) => {
        if (!isAuthenticated || !session || !user) {
            throw new Error("Active session required to send message");
        }
        await dispatch(sendMessageAction(payload)).unwrap();
    };

    return {
        messages,
        loading,
        error,
        sendMessage,
        refresh
    };
}
