'use client';

import { use, useEffect } from "react";
import ChatArea from "@/components/room/ChatArea";
import RoomDetails from "@/components/room/RoomDetails";
import { useRouter } from "next/navigation";
import { RoomService } from "@/services/room.service";

// Hooks
import { useRoom } from "@/hooks/useRoom";
import { useRoomMembers } from "@/hooks/useRoomMembers";
import { useMessages } from "@/hooks/useMessages";
import { useSession } from "@/hooks/useSession";
import { useAppDispatch } from "@/store/hooks";
import { exitRoom, joinRoom } from "@/store/slices/roomSlice";

export default function RoomPage({ params }: { params: Promise<{ roomId: string }> }) {
    const { roomId } = use(params);
    const router = useRouter();
    const dispatch = useAppDispatch();

    // Hooks
    const { session, user, loading: authLoading, isAuthenticated } = useSession();
    const { room, loading: roomLoading } = useRoom(roomId);
    const { members } = useRoomMembers(roomId);
    const { messages, loading: messagesLoading, sendMessage } = useMessages(roomId);

    // Auth Protection
    useEffect(() => {
        if (!authLoading && !isAuthenticated) {
            router.push('/session');
        }
    }, [isAuthenticated, authLoading, router]);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            dispatch(exitRoom());
        };
    }, [dispatch]);

    // Join Room Logic (Auto-join if visiting)
    useEffect(() => {
        // Only if fully loaded and authenticated
        if (isAuthenticated && user && room && room.$id === roomId) {
            dispatch(joinRoom({
                room: room.$id,
                user: user.userId,
                role: room.creator.$id === user.userId ? 'CREATOR' : 'MEMBER'
            }));
        }
    }, [dispatch, isAuthenticated, user, room, roomId]);

    const handleCloseRoom = async () => {
        if (!room) return;
        if (confirm("Are you sure you want to close this room? It will be read-only.")) {
            try {
                await RoomService.close(room.$id);
            } catch (e) {
                console.error(e);
                alert("Failed to close room");
            }
        }
    };

    if (authLoading || (!room && roomLoading)) {
        return <div className="h-screen w-full flex items-center justify-center bg-surface-base dark:bg-surface-darkBase text-text-muted dark:text-text-darkMuted">Loading...</div>;
    }

    if (!session) {
        return null;
    }

    return (
        <>
            <ChatArea
                room={room}
                messages={messages}
                loading={messagesLoading}
                currentUser={user?.userId || null}
                onSendMessage={sendMessage}
            />
            <RoomDetails
                room={room}
                members={members}
                messages={messages}
                currentUserId={user?.userId || null}
                onCloseRoom={handleCloseRoom}
            />
        </>
    );
}
